mapper.insert:
	INSERT /* SQL_ID: PropertyMapper.insertProperty */
      INTO dtmeta.tb_meta_property
		 ( 
		   prpty_id
		 , up_prpty_id
		 , prpty_nm
		 , prpty_logic_nm
		 , prpty_desc
		 , prpty_data_sttus_mtcd
		 , prpty_sort_odrg
		 , cnt_prpty_yn
		 , cnt_model_id
		 , data_array_yn
		 , prpty_scrn_indc_yn
		 , prpty_regr_id
		 , prpty_regr_nm
		 , prpty_reg_dt
		 , prpty_amdr_id
		 , prpty_amdr_nm
		 , prpty_amd_dt
		 ) 
    VALUES 
		 ( 
		   #{prptyId}
		 , #{upPrptyId}
		 , #{prptyNm}
		 , #{prptyLogicNm}
		 , #{prptyDesc}
		 , #{prptyDataSttusMtcd}
		 , #{prptySortOdrg}::numeric
		 , #{cntPrptyYn}
		 , #{cntModelId}
		 , #{dataArrayYn}
		 , #{prptyScrnIndcYn}
		 , #{prptyRegrId}
		 , #{prptyRegrNm}
		 , current_timestamp
		 , #{prptyAmdrId}
		 , #{prptyAmdrNm}
		 , current_timestamp
		 )


	SELECT CONCAT('PD', EXTRACT(EPOCH FROM now())::int, LPAD(CAST(NEXTVAL('dtmeta.seq_tb_meta_common') AS varchar), 4, '0'))	

	INSERT /* SQL_ID: PropertyMapper.insertPropertyDefine */
	  INTO dtmeta.tb_meta_propertydefine
		 ( 
		   prpty_def_id
		 , prpty_id
		 , domn_model_id
		 , range_model_id
		 , range_mtcd_grp_id
		 , ref_prpty_id
		 , prpty_def_chg_yn
		 , prpty_def_chgr_id
		 , prpty_def_chgr_nm
		 , prpty_def_chg_dt
		 , prpty_def_chg_why
		 , prpty_def_regr_id
		 , prpty_def_regr_nm
		 , prpty_def_reg_dt
		 , prpty_def_amdr_id
		 , prpty_def_amdr_nm
		 , prpty_def_amd_dt
		 ) 
    VALUES 
		 ( 
	       #{prptyDefId}    
	     , #{prptyId}    
		 , #{domnModelId}   
		 , #{rangeModelId}  
		 , #{rangeMtcdGrpId}
		 , #{refPrptyId} 
		 , #{prptyDefChgYn} 
		 , #{prptyDefChgrId}
		 , #{prptyDefChgrNm}
		 , #{prptyDefChgDt} 
		 , #{prptyDefChgWhy}
		 , #{prptyDefRegrId}
		 , #{prptyDefRegrNm}
		 , current_timestamp
		 , #{prptyDefAmdrId}
		 , #{prptyDefAmdrNm}
		 , current_timestamp
		 )

mapper.update:
		UPDATE /* SQL_ID: PropertyMapper.updateProperty */
               dtmeta.tb_meta_property
		   SET up_prpty_id				= #{upPrptyId}
			 , prpty_logic_nm			= #{prptyLogicNm}
			 , prpty_desc			    = #{prptyDesc}
			 , prpty_data_sttus_mtcd    = #{prptyDataSttusMtcd}
			 , prpty_sort_odrg          = #{prptySortOdrg}::numeric
			 , cnt_prpty_yn             = #{cntPrptyYn}
			 , cnt_model_id             = #{cntModelId}
			 , prpty_scrn_indc_yn       = #{prptyScrnIndcYn}
			 , prpty_amdr_id            = #{prptyAmdrId}
			 , prpty_amdr_nm            = #{prptyAmdrNm}
			 , prpty_amd_dt	            = current_timestamp
		 WHERE prpty_id		        	= #{prptyId}

		UPDATE /* SQL_ID: PropertyMapper.updateProperty */
               dtmeta.tb_meta_propertydefine
		   SET domn_model_id     = #{domnModelId}
			 , range_model_id    = #{rangeModelId}  
			 , range_mtcd_grp_id = #{rangeMtcdGrpId}
			 , ref_prpty_id      = #{refPrptyId}
			 , prpty_def_chg_yn  = #{prptyDefChgYn}
			 , prpty_def_chgr_id = #{prptyDefChgrId}
			 , prpty_def_chgr_nm = #{prptyDefChgrNm}
			 , prpty_def_chg_dt  = current_timestamp 
			 , prpty_def_chg_why = #{prptyDefChgWhy}
			 , prpty_def_amdr_id = #{prptyDefAmdrId}
			 , prpty_def_amdr_nm = #{prptyDefAmdrNm}
			 , prpty_def_amd_dt  = current_timestamp
		 WHERE prpty_id          = #{prptyId}
		   AND prpty_def_chg_yn  = 'N'

mapper.select:
SELECT /* SQL_ID: PropertyMapper.selectTypePropertyList */ (ROW_NUMBER() OVER(ORDER BY prpty.prpty_sort_odrg)) AS model_prpty_sort_odrg ,prpty.prpty_sort_odrg ,prpty.prpty_nm ,prpty.prpty_logic_nm ,'' AS model_prpty_mand_mtcd_nm ,prpty.cnt_prpty_yn ,prpty.data_array_yn ,def.range_model_id ,model.model_nm AS range_model_nm ,model.model_data_sttus_mtcd AS range_model_data_sttus_mtcd ,model.data_type_mtcd ,prpty.prpty_id ,model.data_type_val_exam AS model_prpty_val_exam ,modelPrpty.model_prpty_id FROM dtmeta.tb_meta_propertydefine def INNER JOIN dtmeta.tb_meta_property prpty on def.prpty_id = prpty.prpty_id AND prpty.prpty_data_sttus_mtcd = 'use' LEFT JOIN dtmeta.tb_meta_model model on def.range_model_id = model.model_id LEFT JOIN dtmeta.tb_meta_modelproperty modelPrpty on modelPrpty.model_id = #{modelId} and modelPrpty.prpty_id = def.prpty_id WHERE (def.domn_model_id = 'Class' OR def.domn_model_id = #{modelId}) AND def.prpty_def_chg_yn = 'N'
AND (UPPER(prpty.prpty_nm) LIKE UPPER('%'||#{searchName}||'%') OR UPPER(prpty.prpty_logic_nm) LIKE UPPER('%'||#{searchName}||'%'))
AND def.domn_model_id = #{domnModelId}
